import json,pathlib,copy
r=pathlib.Path('C:/lesiteinternetquitue/docs/encyclopedia-revision')
base=json.loads((r/'assignments/cannabinoids.json').read_text(encoding='utf-8-sig'))
orig={s['id']:s for s in base['sources']}
p=r/'batches/cannabinoids-02.json'; b=json.loads(p.read_text(encoding='utf-8'))
a=next(a for a in b['articles'] if a['id']=='ref-decouvertes-cannabinoides')
def add(sid,title,url,org,passage,access,limitation):
 s=copy.deepcopy(orig.get(sid,dict(id=sid,title=title,organization=org,author='',published='1990',documentKind='Notice bibliographique')))
 s.update(title=title,url=url,organization=org,passage=passage,access=access,verifiedAt='2026-11-14',limitation=limitation)
 s['reviewEvidence']=[dict(url=url,openedAt='2026-11-14',sections=passage,result='Passage réellement ouvert et examiné.',supports=passage,access=access)]
 b['sources']=[old for old in b['sources'] if old['id']!=sid]+[s]
 a['patch']['sourceIds'].append(sid);a['sourceIdsReviewed'].append(sid)
add('qh-sci-oshaughnessy','On the Preparations of the Indian Hemp, or Gunjah','https://www.gutenberg.org/files/67959/67959-h/67959-h.htm','Project Gutenberg, transcription d’un document primaire','Page de titre, attribution W. B. O’Shaughnessy et note de réimpression du Provincial Medical Journal de 1843 ; introduction distinguant expériences animales et observations cliniques.','excerpt','PMC protégé par CAPTCHA ; transcription alternative effectivement ouverte. Ne pas déduire une priorité mondiale ni reprendre recettes, posologies, généralisations coloniales et assertions médicales anciennes.')
add('qh-sci-thc','Isolation, Structure, and Partial Synthesis of an Active Constituent of Hashish','https://greenearthmedicinals.com/content/Documents/Science_of_CBD/3_Gaoni1964.pdf','JACS / copie de la première page ACS','Capture d’une page ouverte en PDF puis image embarquée extraite et examinée : titre, Gaoni/Mechoulam, JACS 86, 1646–1647, avril 1964 ; début de l’article, attribution de la structure et séparation du cannabinol.','excerpt','Une première page basse résolution, pas l’article entier. L’affiliation du laboratoire ne figure pas lisiblement sur cette page ; aucune recette ni condition de fabrication reprise.')
add('qh-sci-cb1-catalogue','Structure of a cannabinoid receptor and functional expression of the cloned cDNA','https://jglobal.jst.go.jp/en/detail?JGLOBAL_ID=200902017692488948','Japan Science and Technology Agency, J-GLOBAL','Notice : Matsuda, Lolait, Brownstein, Young, Bonner ; titre, Nature 346, 561–564, 9 août 1990 ; affiliation NIMH.','catalogue','Notice bibliographique lue ; résumé expérimental non visible. Pour les dates CB1/CB2 et les distributions générales, recoupement avec le résumé Howlett effectivement lu.')
s0=a['patch']['sections'][0]
s0['paragraphs'][0]='W. B. O’Shaughnessy signe un article sur les préparations de chanvre indien réimprimé en 1843. L’introduction distingue expériences animales et observations de patients atteints notamment de tétanos. Ce document du XIXe siècle n’est pas un essai contrôlé moderne et ne suffit pas à attribuer une première utilisation mondiale. Les travaux de Wood, Spivey et Easterfield restent un jalon à recontrôler dans les originaux devenus inaccessibles ; ils ne servent plus ici de preuve à une réponse de quiz.'
s0['paragraphs'].append('La première page de Gaoni et Mechoulam, publiée en avril 1964 dans le JACS sous le titre Isolation, Structure, and Partial Synthesis of an Active Constituent of Hashish, annonce une attribution structurale du constituant aujourd’hui appelé Δ9-THC. Elle distingue aussi le cannabinol lors de la séparation décrite. La formule historique et la numérotation employée ne doivent pas être lues sans tenir compte des conventions de nomenclature de l’époque ; ce jalon chimique n’est pas une démonstration clinique.')
s0['sourceIds']=['qh-sci-oshaughnessy','qh-sci-cbd-structure','qh-sci-thc']
s1=a['patch']['sections'][1]
s1['paragraphs'].append('La notice bibliographique J-GLOBAL attribue l’article de clonage publié dans Nature le 9 août 1990 à Matsuda, Lolait, Brownstein, Young et Bonner. Le résumé Howlett confirme la chronologie CB1 en 1990 puis CB2 en 1993 et la prédominance neuronale de CB1, immunitaire de CB2. Les détails de la première localisation splénique et la date précise de l’identification de sites avant clonage restent à relire dans les originaux.')
s1['sourceIds']=['qh-sci-receptors','qh-sci-cb1-catalogue']
s2=a['patch']['sections'][2]
s2['paragraphs'].append('Dans l’AEA, la liaison amide unit la partie arachidonoyle à une éthanolamine ; son hydrolyse libère ces deux parties. Cela diffère du 2-AG, où l’acide gras est lié au glycérol par une fonction ester. Le nom anandamide et sa formation historique ne sont pas ici utilisés pour soutenir une question étymologique, faute de passage original lisible sur ce point.')
s2['sourceIds']=['cb-anandamide-1992','cb-2ag-1995','cb-2ag-gut-1995','qh-sci-faah','qh-sci-magl','qh-sci-dagl','qh-sci-cbga']
mapping={'qh-sci-cb1':'qh-sci-receptors','qh-sci-cb2':'qh-sci-receptors','qh-sci-anandamide':'cb-anandamide-1992','qh-sci-2ag':'cb-2ag-1995','qh-sci-faah-products':'qh-sci-faah','qh-sci-cb1-history':'qh-sci-receptors'}
changes={
'hemp-hs-sci-cbd-1940':dict(prompt='Quel cannabinoïde Gaoni et Mechoulam distinguent-ils du THC dans la première page de leur publication de 1964 ?',sourceIds=['qh-sci-thc'],explanation='La première page distingue le cannabinol du constituant actif étudié. La question sur Wood, Spivey et Easterfield est remplacée car leur document original n’a pas pu être ouvert.'),
'hemp-hs-sci-cb2':dict(prompt='Quel récepteur cannabinoïde a été cloné en 1993, après CB1 ?',explanation='Le résumé Howlett de 2002 récapitule les dates : CB1 en 1990, CB2 en 1993 ; l’adjectif périphérique ne signifie pas une distribution exclusivement périphérique.'),
'hemp-hs-sci-anandamide-name':dict(prompt='À quelle petite molécule la partie arachidonoyle est-elle liée dans l’anandamide ?',options=['Éthanolamine','Glycérol','Glucose','Cholestérol'],answer=0,sourceIds=['cb-anandamide-1992','qh-sci-faah'],explanation='L’AEA est une N-arachidonoyléthanolamide. La question étymologique est remplacée faute de passage original accessible sur le nom sanskrit.'),
'hemp-hs-sci-cb1-brain':dict(prompt='Dans quel ensemble de cellules CB1 est-il principalement présent selon la classification Howlett de 2002 ?',options=['Neurones centraux et périphériques','Globules rouges uniquement','Cellules végétales uniquement','Levures uniquement'],answer=0,sourceIds=['qh-sci-receptors'],explanation='Le résumé décrit une prédominance dans les neurones centraux et périphériques ; ce n’est pas une exclusivité et des cellules immunitaires peuvent aussi exprimer CB1.'),
'hemp-hs-sci-mechoulam-country':dict(prompt='Dans quel pays se situe l’Institut Weizmann cité dans l’article de Mechoulam et Shvo sur le CBD en 1963 ?',sourceIds=['qh-sci-cbd-structure'],explanation='La première page effectivement lue donne Rehovot, Israël ; la question porte sur cette affiliation de 1963, pas sur une affiliation supposée de la page de 1964.'),
'hemp-hs-sci-cb1-clone':dict(sourceIds=['qh-sci-cb1-catalogue','qh-sci-receptors'],explanation='La notice bibliographique de l’article Nature de 1990 donne Matsuda, Lolait, Brownstein, Young et Bonner. Le résumé Howlett confirme qu’il s’agit du jalon CB1.'),
'hemp-hs-sci-cb2-tissue':dict(prompt='Quel type de cellules exprime principalement CB2 selon la classification Howlett de 2002 ?',options=['Cellules immunitaires','Globules rouges uniquement','Cellules des feuilles','Cellules de levure'],answer=0,sourceIds=['qh-sci-receptors'],explanation='Le résumé indique une présence principalement immunitaire. L’ancienne précision sur les macrophages de la rate reste à vérifier dans l’original Munro, inaccessible dans cette session.'),
'hemp-hs-sci-anandamide-molecule':dict(options=['N-arachidonoyléthanolamide','2-arachidonoylglycérol','Acide olivétolique','Cannabinol'],answer=0,explanation='L’anandamide est une N-arachidonoyléthanolamide ; AEA est une amide et le 2-AG est un ester du glycérol.'),
'hemp-hs-sci-cb1-discovery-v-clone':dict(prompt='Quelle chronologie de clonage CB1/CB2 est confirmée par la classification Howlett de 2002 ?',options=['CB1 en 1990, puis CB2 en 1993','CB2 en 1990, puis CB1 en 1993','Les deux en 1964','Les deux en 2020'],answer=0,sourceIds=['qh-sci-receptors'],explanation='Le résumé confirme ces deux années de clonage. La question ne demande plus de dater l’identification de sites en 1988, dont l’original n’a pas été relu ici.')
}
for q in b['quizPatches']:
 if q['articleId']!=a['id']:continue
 q['sourceIds']=list(dict.fromkeys(mapping.get(s,s) for s in q['sourceIds']))
 q.update(changes.get(q['id'],{}))
 assert set(q['sourceIds'])<=set(a['patch']['sourceIds']),(q['id'],q['sourceIds'])
a['blockers']=['Origins Wood/Spivey/Easterfield, détails initiaux du récepteur CB2 et jalon de liaison pré-clonage : documents originaux toujours protégés par CAPTCHA/403. Aucune réponse de quiz ne dépend désormais de ces précisions non relues.','Étymologie historique de l’anandamide non étayée dans les passages originaux accessibles ; question remplacée par la liaison amide documentée.']
a['findings'].append('Tous les quiz remappés aux références effectivement lues ; questions restreintes ou remplacées lorsque la preuve accessible ne soutenait pas le détail demandé. Ajout de trois documents réellement ouverts : transcription O’Shaughnessy, première page Gaoni et notice bibliographique Matsuda.')
a['questions']=[q['prompt'] for q in b['quizPatches'] if q['articleId']==a['id']]
b['sensitivePoints'].append('Contrôle de cohérence : toutes les références des quiz scientifiques historiques sont citées dans la fiche. Les précisions non documentées ne sont pas réintroduites par simple conservation des anciens identifiants.')
p.write_text(json.dumps(b,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
print('Quiz scientifiques : références cohérentes et réellement lues ; blocages conservés, questions non étayées reformulées.')
